automation.exemple_de_configuration_d:
# Example configuration for multipart upload with attachments in an HTTP node:
{
  "method": "POST",
  "url": "https://api.thirdparty.com/v1/documents",
  "auth_type": "bearer",
  "auth_token": "{payload.api_key}",
  "body_type": "form_data",
  "form_fields": {
    "title": "Invoice {payload.invoice_number}",
    "client_id": "{payload.customer_id}"
  },
  "files": [
    {
      "field_name": "document",
      "file_source": "path",
      "file_path": "/var/storage/invoices/inv_{payload.id}.pdf",
      "filename": "invoice_{payload.id}.pdf"
    }
  ]
}
